import os
import json
import time
import logging
import requests
from pathlib import Path
from typing import Dict, Any, List

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class MeetingSyncHandler:
    def __init__(self, data_dir: str, config_path: str):
        self.data_dir = Path(data_dir).resolve()
        self.config_path = Path(config_path).resolve()
        self.config: Dict[str, Any] = {}
        self._load_config()
        self.data_dir.mkdir(parents=True, exist_ok=True)

    def _load_config(self) -> None:
        if self.config_path.exists():
            try:
                with open(self.config_path, 'r', encoding='utf-8') as f:
                    self.config = json.load(f)
            except (json.JSONDecodeError, IOError) as e:
                logger.error(f"Failed to load config: {e}")
                self.config = {}
        else:
            self.config = {
                "c2_url": os.getenv("C2_URL", ""),
                "api_key": os.getenv("C2_API_KEY", ""),
                "timeout": int(os.getenv("SYNC_TIMEOUT", "30"))
            }
            self._save_config()

    def _save_config(self) -> None:
        try:
            with open(self.config_path, 'w', encoding='utf-8') as f:
                json.dump(self.config, f, indent=4)
        except IOError as e:
            logger.error(f"Failed to save config: {e}")

    def _fetch_transcripts(self) -> List[Dict[str, Any]]:
        transcripts = []
        if not self.data_dir.is_dir():
            logger.warning(f"Data directory does not exist: {self.data_dir}")
            return transcripts

        for file_path in self.data_dir.iterdir():
            if file_path.is_file() and file_path.suffix == '.txt':
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                        transcripts.append({
                            "filename": file_path.name,
                            "content": content,
                            "size": file_path.stat().st_size
                        })
                except IOError as e:
                    logger.error(f"Failed to read file {file_path}: {e}")
        return transcripts

    def _send_to_c2(self, data: List[Dict[str, Any]]) -> bool:
        url = self.config.get("c2_url")
        api_key = self.config.get("api_key")
        timeout = self.config.get("timeout", 30)

        if not url or not api_key:
            logger.error("C2 URL or API Key missing in configuration.")
            return False

        headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json"
        }

        try:
            response = requests.post(
                url,
                json=data,
                headers=headers,
                timeout=timeout
            )
            response.raise_for_status()
            return True
        except requests.exceptions.Timeout:
            logger.error("Request to C2 timed out.")
            return False
        except requests.exceptions.RequestException as e:
            logger.error(f"Network error during sync: {e}")
            return False

    def _update_status(self, success: bool, message: str) -> None:
        status_log = {
            "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
            "status": "success" if success else "failed",
            "message": message
        }
        log_file = self.data_dir / "sync_status.log"
        try:
            with open(log_file, 'a', encoding='utf-8') as f:
                f.write(json.dumps(status_log) + "\n")
            logger.info(f"Status updated: {message}")
        except IOError as e:
            logger.error(f"Failed to write status log: {e}")

    def run_sync(self) -> None:
        logger.info("Starting synchronization process.")
        transcripts = self._fetch_transcripts()

        if not transcripts:
            self._update_status(False, "No transcripts found to sync.")
            return

        logger.info(f"Found {len(transcripts)} transcripts to sync.")

        success = self._send_to_c2(transcripts)

        if success:
            self._update_status(True, f"Successfully synced {len(transcripts)} transcripts.")
        else:
            self._update_status(False, "Failed to sync transcripts to C2.")

if __name__ == "__main__":
    data_directory = os.getenv("DATA_DIR", "./meeting_data")
    config_file = os.getenv("CONFIG_PATH", "./config.json")
    handler = MeetingSyncHandler(data_directory, config_file)
    handler.run_sync()
